PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "alineaciones" (
      id_alineacion INTEGER PRIMARY KEY,
      id_partido INTEGER NOT NULL,
      id_jugadora INTEGER NOT NULL,
      convocada INTEGER NOT NULL,
      titular INTEGER NOT NULL,
      minutos_jugados INTEGER NOT NULL,
      minuto_entrada INTEGER,
      minuto_salida INTEGER,
      FOREIGN KEY (id_partido) REFERENCES partidos(id_partido) ON DELETE CASCADE,
      FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora),
      UNIQUE (id_partido, id_jugadora)
    );
CREATE TABLE `arbitras` (
`id_arbitra` INTEGER PRIMARY KEY,
`nombre` VARCHAR(100) DEFAULT NULL
, foto_url TEXT, `pais_origen` text, `iso` text, `colegio` text);
CREATE TABLE categorias (
    id_categoria INTEGER PRIMARY KEY,
    nombre TEXT NOT NULL,
    slug   TEXT NOT NULL UNIQUE,
    nivel  INTEGER NOT NULL
  );
CREATE TABLE "clubes" (
      id_club INTEGER PRIMARY KEY,
      nombre VARCHAR(200) NOT NULL,
      ciudad VARCHAR(50),
      pais VARCHAR(50),
      slug TEXT UNIQUE,
      estadio INTEGER,
      foto_url TEXT,
      iso TEXT
    );
CREATE TABLE "competiciones" (
      id_competicion INTEGER PRIMARY KEY,
      competicion VARCHAR(50) NOT NULL UNIQUE,
      foto_url TEXT
    );
CREATE TABLE contratos (
        id_contrato INTEGER PRIMARY KEY AUTOINCREMENT,
        id_jugadora INTEGER NOT NULL,
        fecha_inicio DATE,
        fecha_fin DATE,
        valor_mercado REAL,
        FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
      );
CREATE TABLE "dorsales" (
      id_dorsal INTEGER PRIMARY KEY AUTOINCREMENT,
      id_jugadora INTEGER NOT NULL,
      id_temporada INTEGER NOT NULL,
      dorsal TEXT NOT NULL,
      id_club INTEGER,
      fecha_debut TEXT,
      foto_url TEXT,
      foto_perfil_url TEXT,
      id_categoria INTEGER NOT NULL DEFAULT 4,
      FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora),
      FOREIGN KEY (id_club) REFERENCES clubes(id_club),
      FOREIGN KEY (id_temporada) REFERENCES temporadas(id_temporada),
      FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria),
      UNIQUE (id_jugadora, id_temporada, id_categoria)
    );
CREATE TABLE `entrenadores` (
`id_entrenador` INTEGER PRIMARY KEY,
`nombre` VARCHAR(200) DEFAULT NULL,
`ciudad` VARCHAR(100) DEFAULT NULL,
`pais` VARCHAR(100) DEFAULT NULL,
`fecha_nacimiento` DATE DEFAULT NULL
, foto_url TEXT, `iso` text);
CREATE TABLE equipaciones (
        id_equipacion INTEGER PRIMARY KEY AUTOINCREMENT,
        id_temporada INTEGER,
        nombre TEXT, -- Ej: 'Primera Equipación 23/24'
        tipo TEXT,   -- 'Local', 'Visitante', 'Tercera', 'Portera'
        imagen_url TEXT, -- URL de la foto de la camiseta
        FOREIGN KEY (id_temporada) REFERENCES temporadas(id_temporada)
      );
CREATE TABLE "estadios" (
      id_estadio INTEGER PRIMARY KEY,
      nombre VARCHAR(100),
      ciudad VARCHAR(50),
      pais VARCHAR(50),
      capacidad INTEGER,
      foto_url TEXT,
      lat REAL,
      lng REAL
    );
CREATE TABLE estadisticas_jugadoras (
                id_est_jugadora INTEGER PRIMARY KEY AUTOINCREMENT,
                id_partido INTEGER NOT NULL,
                id_jugadora INTEGER NOT NULL,
                
                -- Rendimiento General
                valoracion REAL,
                
                -- Ataque y Tiros
                tiros_totales INTEGER DEFAULT 0,
                tiros_puerta INTEGER DEFAULT 0,
                toques INTEGER DEFAULT 0,
                toques_area_rival INTEGER DEFAULT 0,
                regates_totales INTEGER DEFAULT 0,
                regates_completados INTEGER DEFAULT 0,
                perdidas INTEGER DEFAULT 0,
                fueras_juego INTEGER DEFAULT 0,
                
                -- Pases y Creación
                pases_totales INTEGER DEFAULT 0,
                pases_completados INTEGER DEFAULT 0,
                pases_clave INTEGER DEFAULT 0,
                pases_ultimo_tercio INTEGER DEFAULT 0,
                pases_largo_totales INTEGER DEFAULT 0,
                pases_largo_completados INTEGER DEFAULT 0,
                centros_totales INTEGER DEFAULT 0,
                centros_completados INTEGER DEFAULT 0,
                entradas INTEGER DEFAULT 0,
                bloqueos INTEGER DEFAULT 0,
                despejes INTEGER DEFAULT 0,
                intercepciones INTEGER DEFAULT 0,
                recuperaciones INTEGER DEFAULT 0,
                regateada INTEGER DEFAULT 0,
                duelos_suelo_totales INTEGER DEFAULT 0,
                duelos_suelo_ganados INTEGER DEFAULT 0,
                duelos_aereos_totales INTEGER DEFAULT 0,
                duelos_aereos_ganados INTEGER DEFAULT 0,
                
                -- Disciplina
                faltas_recibidas INTEGER DEFAULT 0,
                faltas_cometidas INTEGER DEFAULT 0, pases_ultimo_tercio_totales INTEGER DEFAULT 0, pases_ultimo_tercio_completados INTEGER DEFAULT 0,

                FOREIGN KEY (id_partido) REFERENCES partidos(id_partido),
                FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
            );
CREATE TABLE "estadisticas_partidos" (
    id_partido INTEGER PRIMARY KEY,
    posesion_rm INTEGER,
    posesion_rival INTEGER,
    xg_a_favor REAL,
    xg_en_contra REAL,
    faltas_cometidas INTEGER,
    faltas_recibidas INTEGER
, rm_grandes_ocasiones INTEGER DEFAULT 0, rm_tiros INTEGER DEFAULT 0, rm_tiros_puerta INTEGER DEFAULT 0, rm_tiros_palo INTEGER DEFAULT 0, rm_paradas INTEGER DEFAULT 0, rm_corners INTEGER DEFAULT 0, rm_pases_totales INTEGER DEFAULT 0, rm_pases_completados INTEGER DEFAULT 0, rm_pases_largo_totales INTEGER DEFAULT 0, rm_pases_largo_completados INTEGER DEFAULT 0, rm_pases_tercio_totales INTEGER DEFAULT 0, rm_pases_tercio_completados INTEGER DEFAULT 0, rm_centros_totales INTEGER DEFAULT 0, rm_centros_completados INTEGER DEFAULT 0, rm_toques_area_rival INTEGER DEFAULT 0, rm_entradas_totales INTEGER DEFAULT 0, rm_entradas_ganadas INTEGER DEFAULT 0, rm_tiros_libres INTEGER DEFAULT 0, rm_duelos_suelo_totales INTEGER DEFAULT 0, rm_duelos_suelo_ganados INTEGER DEFAULT 0, rm_duelos_aereos_totales INTEGER DEFAULT 0, rm_duelos_aereos_ganados INTEGER DEFAULT 0, rm_regates INTEGER DEFAULT 0, rm_intercepciones INTEGER DEFAULT 0, rm_recuperaciones INTEGER DEFAULT 0, rm_despejes INTEGER DEFAULT 0, rm_fueras_juego INTEGER DEFAULT 0, rm_asistencias_esperadas REAL DEFAULT 0.0, rival_grandes_ocasiones INTEGER DEFAULT 0, rival_tiros INTEGER DEFAULT 0, rival_tiros_puerta INTEGER DEFAULT 0, rival_tiros_palo INTEGER DEFAULT 0, rival_paradas INTEGER DEFAULT 0, rival_corners INTEGER DEFAULT 0, rival_pases_totales INTEGER DEFAULT 0, rival_pases_completados INTEGER DEFAULT 0, rival_pases_largo_totales INTEGER DEFAULT 0, rival_pases_largo_completados INTEGER DEFAULT 0, rival_pases_tercio_totales INTEGER DEFAULT 0, rival_pases_tercio_completados INTEGER DEFAULT 0, rival_centros_totales INTEGER DEFAULT 0, rival_centros_completados INTEGER DEFAULT 0, rival_toques_area_rival INTEGER DEFAULT 0, rival_entradas_totales INTEGER DEFAULT 0, rival_entradas_ganadas INTEGER DEFAULT 0, rival_tiros_libres INTEGER DEFAULT 0, rival_duelos_suelo_totales INTEGER DEFAULT 0, rival_duelos_suelo_ganados INTEGER DEFAULT 0, rival_duelos_aereos_totales INTEGER DEFAULT 0, rival_duelos_aereos_ganados INTEGER DEFAULT 0, rival_regates INTEGER DEFAULT 0, rival_intercepciones INTEGER DEFAULT 0, rival_recuperaciones INTEGER DEFAULT 0, rival_despejes INTEGER DEFAULT 0, rival_fueras_juego INTEGER DEFAULT 0, rival_asistencias_esperadas REAL DEFAULT 0.0, FOREIGN KEY (id_partido) REFERENCES partidos(id_partido) ON DELETE CASCADE);
CREATE TABLE "goles_propia" (
      id_autogol INTEGER PRIMARY KEY AUTOINCREMENT,
      id_partido INTEGER NOT NULL,
      id_jugadora INTEGER REFERENCES jugadoras(id_jugadora),
      rival_nombre TEXT,
      minuto TEXT,
      FOREIGN KEY(id_partido) REFERENCES partidos(id_partido),
      CHECK (
        (id_jugadora IS NOT NULL AND rival_nombre IS NULL) OR
        (id_jugadora IS NULL AND rival_nombre IS NOT NULL)
      )
    );
CREATE TABLE goles_rival (
                id_gol_rival INTEGER PRIMARY KEY AUTOINCREMENT,
                id_partido INTEGER NOT NULL,
                goleadora TEXT NOT NULL,
                asistente TEXT,
                minuto TEXT NOT NULL,
                tipo TEXT,
                FOREIGN KEY(id_partido) REFERENCES partidos(id_partido)
            );
CREATE TABLE "goles_y_asistencias" (
      id_gol INTEGER PRIMARY KEY,
      goleadora INTEGER,
      asistente INTEGER,
      id_partido INTEGER NOT NULL,
      goles_a_favor INTEGER NOT NULL,
      goles_en_contra INTEGER NOT NULL,
      minuto TEXT NOT NULL,
      parte_cuerpo TEXT,
      tipo TEXT,
      video_url TEXT,
      FOREIGN KEY (id_partido) REFERENCES partidos(id_partido) ON DELETE CASCADE,
      FOREIGN KEY (goleadora) REFERENCES jugadoras(id_jugadora) ON DELETE SET NULL,
      FOREIGN KEY (asistente) REFERENCES jugadoras(id_jugadora) ON DELETE SET NULL
    );
CREATE TABLE "jugadoras" (
      id_jugadora INTEGER PRIMARY KEY,
      nombre VARCHAR(200) NOT NULL,
      fecha_nacimiento DATE,
      pais_origen VARCHAR(50),
      altura DECIMAL(4,2),
      peso DECIMAL(5,2),
      posicion VARCHAR(50),
      lugar_nacimiento TEXT,
      tipo TEXT,
      iso TEXT,
      lat REAL,
      lng REAL
    );
CREATE TABLE lesiones (
        id_lesion INTEGER PRIMARY KEY AUTOINCREMENT,
        id_jugadora INTEGER NOT NULL,
        tipo_lesion TEXT, -- Ej: 'Muscular', 'Ligamento'
        zona_cuerpo TEXT,
        fecha_lesion DATE,
        fecha_alta DATE,
        partidos_perdidos INTEGER,
        FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
      );
CREATE TABLE "mvp" (
    id_premio INTEGER PRIMARY KEY,
    id_jugadora INTEGER,
    tipo TEXT,
    titulo TEXT,
    fecha TEXT, foto_url TEXT,
    FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
);
CREATE TABLE "partidos" (
      id_partido INTEGER PRIMARY KEY,
      fecha DATE,
      hora TIME,
      id_temporada INTEGER,
      id_competicion INTEGER,
      jornada VARCHAR(50),
      id_club_local INTEGER,
      id_club_visitante INTEGER,
      id_estadio INTEGER,
      goles_rm INTEGER,
      goles_rival INTEGER,
      id_arbitra INTEGER,
      id_entrenador INTEGER,
      penaltis BOOLEAN,
      asistencia INTEGER,
      mvp INTEGER,
      capitana INTEGER,
      mvp_foto_url TEXT,
      once_inicial_url TEXT,
      formacion TEXT,
      tv TEXT,
      tiempo_partido TEXT,
      id_equipacion INTEGER,
      FOREIGN KEY (id_temporada) REFERENCES temporadas(id_temporada),
      FOREIGN KEY (id_competicion) REFERENCES competiciones(id_competicion),
      FOREIGN KEY (id_club_local) REFERENCES clubes(id_club),
      FOREIGN KEY (id_club_visitante) REFERENCES clubes(id_club),
      FOREIGN KEY (id_estadio) REFERENCES estadios(id_estadio),
      FOREIGN KEY (id_arbitra) REFERENCES arbitras(id_arbitra),
      FOREIGN KEY (id_entrenador) REFERENCES entrenadores(id_entrenador),
      FOREIGN KEY (mvp) REFERENCES jugadoras(id_jugadora),
      FOREIGN KEY (capitana) REFERENCES jugadoras(id_jugadora),
      FOREIGN KEY (id_equipacion) REFERENCES equipaciones(id_equipacion)
    );
CREATE TABLE penaltis_fallados (
                id_penalti_fallado INTEGER PRIMARY KEY AUTOINCREMENT,
                id_partido INTEGER NOT NULL,
                id_jugadora INTEGER, -- NULL si es rival
                nombre_rival TEXT,   -- NULL si es jugadora del equipo
                minuto TEXT,
                video_url TEXT,         -- 'Parada', 'Fuera', 'Palo'
                FOREIGN KEY (id_partido) REFERENCES partidos(id_partido),
                FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
            );
CREATE TABLE redes_sociales (
        id_jugadora INTEGER PRIMARY KEY,
        url_instagram TEXT,
        url_x TEXT,
        url_tiktok TEXT,
        FOREIGN KEY (id_jugadora) REFERENCES jugadoras(id_jugadora)
      );
CREATE TABLE "tanda_penaltis" (
    id_penalti_tanda INTEGER PRIMARY KEY AUTOINCREMENT,
    id_partido INTEGER NOT NULL,
    orden INTEGER NOT NULL,  -- 1, 2, 3...
    id_jugadora INTEGER,     -- ID si es del RM. NULL si es rival
    nombre_rival TEXT,       -- Nombre si es Rival. NULL si es RM
    resultado TEXT NOT NULL CHECK(resultado IN ('GOL', 'FALLADO')),
    
    FOREIGN KEY(id_partido) REFERENCES partidos(id_partido),
    FOREIGN KEY(id_jugadora) REFERENCES jugadoras(id_jugadora),
    CHECK (
        (id_jugadora IS NOT NULL AND nombre_rival IS NULL) OR 
        (id_jugadora IS NULL AND nombre_rival IS NOT NULL)
    )
);
CREATE TABLE "tarjetas" (
                id_tarjeta          INTEGER PRIMARY KEY AUTOINCREMENT,
                id_partido          INTEGER NOT NULL,
                id_jugadora         INTEGER NOT NULL,
                tipo_tarjeta        TEXT NOT NULL,
                minuto              TEXT NOT NULL, 
                FOREIGN KEY (id_partido) REFERENCES partidos (id_partido),
                FOREIGN KEY (id_jugadora) REFERENCES jugadoras (id_jugadora)
            );
CREATE TABLE tarjetas_rival (
                id_tarjeta_rival INTEGER PRIMARY KEY AUTOINCREMENT,
                id_partido INTEGER NOT NULL,
                nombre TEXT NOT NULL,
                tipo_tarjeta TEXT NOT NULL,
                minuto TEXT NOT NULL,
                FOREIGN KEY(id_partido) REFERENCES partidos(id_partido)
            );
CREATE TABLE "temporadas" (
      id_temporada INTEGER PRIMARY KEY,
      temporada VARCHAR(50) NOT NULL UNIQUE
    );
CREATE TABLE "trayectoria_entrenadores" (
      id_trayectoria INTEGER PRIMARY KEY AUTOINCREMENT,
      id_entrenador INTEGER NOT NULL,
      club TEXT NOT NULL,
      año_inicio INTEGER,
      año_fin INTEGER,
      FOREIGN KEY (id_entrenador) REFERENCES entrenadores(id_entrenador)
    );
CREATE TABLE "trayectoria_jugadoras" (
    -- Clave Primaria para identificar cada registro de historial (obligatorio)
    "id_trayectoria"        INTEGER PRIMARY KEY AUTOINCREMENT,

    -- Clave Foránea que vincula a la tabla principal de Jugadoras (obligatorio)
    -- Asumimos que tu tabla de jugadoras se llama 'Jugadoras'
    "id_jugadora"         INTEGER NOT NULL,

    -- Nombre del equipo
    "club"       TEXT NOT NULL,

    -- Año de inicio en el equipo (usamos INTEGER para un simple año)
    "año_inicio"         INTEGER NOT NULL,

    -- Año de fin en el equipo. Puede ser NULL si el periodo está incompleto (p. ej., si es el último club antes del Real Madrid)
    "año_fin"            INTEGER,

    -- Definición de la Clave Foránea para asegurar la integridad referencial.
    -- Esto garantiza que no puedas agregar un historial para una jugadora que no existe.
    FOREIGN KEY ("id_jugadora") REFERENCES Jugadoras (ID_Jugadora)
);
', NULL, 4);
