CREATE INDEX idx_alineaciones_core ON alineaciones (id_partido, id_jugadora, titular);
CREATE INDEX idx_alineaciones_eficiente ON alineaciones (id_jugadora, id_partido, titular);
CREATE INDEX idx_autogoles_jug ON goles_propia (id_jugadora);
CREATE INDEX idx_clubes_iso ON clubes (iso);
CREATE INDEX idx_contratos_jugadora ON CONTRATOS (id_jugadora, fecha_fin);
CREATE INDEX idx_dorsales_historial ON dorsales (id_jugadora, id_temporada, dorsal);
CREATE INDEX idx_equipaciones_temp ON EQUIPACIONES (id_temporada);
CREATE INDEX idx_est_jugadora_rendimiento ON ESTADISTICAS_JUGADORAS (id_jugadora, id_partido);
CREATE INDEX idx_est_jugadoras_main ON ESTADISTICAS_JUGADORAS (id_partido, id_jugadora);
CREATE INDEX idx_est_partidos_pk ON estadisticas_partidos (id_partido);
CREATE INDEX idx_estadios_ciudad ON estadios (ciudad);
CREATE INDEX idx_estadios_ubicacion ON estadios (pais, ciudad);
CREATE INDEX idx_goles_asistente ON goles_y_asistencias (asistente);
CREATE INDEX idx_goles_jugadora ON goles_y_asistencias (goleadora, asistente);
CREATE INDEX idx_goles_partido ON goles_y_asistencias (id_partido);
CREATE INDEX idx_lesiones_jugadora ON LESIONES (id_jugadora);
CREATE INDEX idx_mvp_data ON MVP (id_jugadora, tipo, fecha);
CREATE INDEX idx_partidos_calendario ON partidos (fecha, id_temporada, id_competicion);
CREATE INDEX idx_partidos_clubes ON partidos (id_club_local, id_club_visitante);
CREATE INDEX idx_partidos_fecha ON partidos (fecha);
CREATE INDEX idx_partidos_filtros ON partidos (id_temporada, id_competicion);
CREATE INDEX idx_penaltis_fallados_jug ON PENALTIS_FALLADOS (id_jugadora);
CREATE INDEX idx_redes_jugadora ON REDES_SOCIALES (id_jugadora);
CREATE INDEX idx_trayectoria_ent_id ON trayectoria_entrenadores (id_entrenador);
CREATE INDEX idx_trayectoria_jug_id ON TRAYECTORIA_JUGADORAS (id_jugadora);
CREATE UNIQUE INDEX uq_est_jugadora_partido ON estadisticas_jugadoras(id_partido, id_jugadora);
COMMIT;
PRAGMA foreign_keys=ON;
